content:
:root {
  --bg-color: #0f172a;
  --panel-bg: rgba(30, 41, 59, 0.85);
  --text-color: #f8fafc;
  --text-muted: #94a3b8;
  --primary: #3b82f6;
  --primary-hover: #2563eb;
  --border-color: #334155;
  --radius: 12px;
  --shadow-sm: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 25px -5px rgba(0, 0, 0, 0.3);
  --focus-ring: 0 0 0 3px rgba(59, 130, 246, 0.4);
  --transition-fast: 0.2s ease;
  --breakpoint-md: 768px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-color);
  min-height: 100vh;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

.app-container {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  padding: 20px;
  max-width: 1400px;
  margin: 0 auto;
}

.header {
  text-align: center;
  margin-bottom: 20px;
}

.title {
  font-size: 2rem;
  font-weight: 700;
  background: linear-gradient(135deg, #60a5fa, #a78bfa);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 4px;
}

.subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
}

.main-layout {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 20px;
  flex: 1;
  min-height: 500px;
}

@media (max-width: 768px) {
  .main-layout {
    grid-template-columns: 1fr;
  }
}

.canvas-container {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 400px;
  background: radial-gradient(circle at center, #1e293b 0%, #0f172a 100%);
  border-radius: var(--radius);
  border: 1px solid var(--border-color);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}

.canvas-container canvas {
  display: block;
  width: 100% !important;
  height: 100% !important;
  outline: none;
}

.control-panel {
  background: var(--panel-bg);
  backdrop-filter: blur(12px);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  box-shadow: var(--shadow-lg);
  height: fit-content;
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-color);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.btn {
  background-color: var(--primary);
  color: white;
  border: none;
  border-radius: 8px;
  padding: 10px 16px;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color var(--transition-fast), transform 0.1s;
  width: 100%;
  text-align: center;
}

.btn:hover {
  background-color: var(--primary-hover);
}

.btn:active {
  transform: scale(0.98);
}

.btn:focus-visible,
.color-picker:focus-visible,
.range-input:focus-visible,
input[type="checkbox"]:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.color-picker {
  -webkit-appearance: none;
  border: none;
  width: 100%;
  height: 40px;
  border-radius: 8px;
  cursor: pointer;
  background: transparent;
}

.color-picker::-webkit-color-swatch-wrapper {
  padding: 0;
}

.color-picker::-webkit-color-swatch {
  border: 1px solid var(--border-color);
  border-radius: 8px;
}

.range-input {
  width: 100%;
  accent-color: var(--primary);
  cursor: pointer;
}

input[type="checkbox"] {
  accent-color: var(--primary);
  width: 18px;
  height: 18px;
  cursor: pointer;
}

/**
 * 3D立方体の表示・動作設定を保持するインターフェース
 */
export interface CubeConfig {
  /** 立方体の色（HEXカラーコードなど） */
  color: string;
  /** ワイヤーフレーム表示の有効/無効 */
  wireframe: boolean;
  /** 自動回転の有効/無効 */
  autoRotate: boolean;
  /** 回転速度の倍率 */
  speed: number;
  /** 将来の拡張用プロパティを許容するインデクスシグネチャ */
  [key: string]: unknown;
}

import { useEffect, useRef } from 'react'
import * as THREE from 'three'
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js'
import { CubeConfig } from './types'
import './index.css'

interface CubeCanvasProps {
  config: CubeConfig;
}

export default function CubeCanvas({ config }: CubeCanvasProps) {
  const mountRef = useRef<HTMLDivElement>(null);
  const cubeRef = useRef<THREE.Mesh | null>(null);
  const materialRef = useRef<THREE.MeshStandardMaterial | null>(null);
  const configRef = useRef(config);

  // Keep ref updated to prevent closure stale values in animation loop
  useEffect(() => {
    configRef.current = config;
  }, [config]);

  useEffect(() => {
    const currentMount = mountRef.current;
    if (!currentMount) return;

    // Scene
    const scene = new THREE.Scene();

    // Camera
    const camera = new THREE.PerspectiveCamera(
      75,
      currentMount.clientWidth / currentMount.clientHeight,
      0.1,
      1000
    );
    camera.position.z = 5;

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setSize(currentMount.clientWidth, currentMount.clientHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    currentMount.appendChild(renderer.domElement);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;

    // Light
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.7);
    scene.add(ambientLight);

    const pointLight = new THREE.PointLight(0xffffff, 1);
    pointLight.position.set(5, 5, 5);
    scene.add(pointLight);

    // Cube
    const geometry = new THREE.BoxGeometry(2, 2, 2);
    const material = new THREE.MeshStandardMaterial({
      color: configRef.current.color,
      wireframe: configRef.current.wireframe,
    });
    materialRef.current = material;

    const cube = new THREE.Mesh(geometry, material);
    scene.add(cube);
    cubeRef.current = cube;

    // Resize Handler with Debounce
    let resizeTimeout: NodeJS.Timeout;
    const handleResize = () => {
      clearTimeout(resizeTimeout);
      resizeTimeout = setTimeout(() => {
        if (!currentMount) return;
        camera.aspect = currentMount.clientWidth / currentMount.clientHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(currentMount.clientWidth, currentMount.clientHeight);
      }, 100);
    };

    window.addEventListener('resize', handleResize);

    // Animation Loop
    let animationFrameId: number;
    const animate = () => {
      animationFrameId = requestAnimationFrame(animate);

      if (configRef.current.autoRotate && cubeRef.current) {
        cubeRef.current.rotation.x += 0.01 * configRef.current.speed;
        cubeRef.current.rotation.y += 0.015 * configRef.current.speed;
      }

      controls.update();
      renderer.render(scene, camera);
    };

    animate();

    return () => {
      window.removeEventListener('resize', handleResize);
      clearTimeout(resizeTimeout);
      cancelAnimationFrame(animationFrameId);
      controls.dispose();

      geometry.dispose();
      material.dispose();
      renderer.dispose();

      if (currentMount.contains(renderer.domElement)) {
        currentMount.removeChild(renderer.domElement);
      }
    };
  }, []);

  // Update material properties dynamically
  useEffect(() => {
    if (materialRef.current) {
      materialRef.current.color.set(config.color);
      materialRef.current.wireframe = config.wireframe;
    }
  }, [config.color, config.wireframe]);

  return <div className="canvas-container" ref={mountRef} />;
}

import { CubeConfig } from './types'
import './index.css'

interface ControlPanelProps {
  config: CubeConfig;
  onChange: (newConfig: CubeConfig) => void;
  onReset: () => void;
}

export default function ControlPanel({ config, onChange, onReset }: ControlPanelProps) {
  const handleChange = <K extends keyof CubeConfig>(key: K, value: CubeConfig[K]) => {
    onChange({
      ...config,
      [key]: value,
    });
  };

  return (
    <div className="control-panel">
      <div className="control-group">
        <label className="label" htmlFor="cube-color-picker">
          立方体の色
        </label>
        <input
          id="cube-color-picker"
          type="color"
          className="color-picker"
          value={config.color}
          onChange={(e) => handleChange('color', e.target.value)}
          aria-label="立方体の色"
        />
      </div>

      <div className="control-group">
        <label className="label" htmlFor="cube-wireframe-checkbox">
          ワイヤーフレーム
          <input
            id="cube-wireframe-checkbox"
            type="checkbox"
            checked={config.wireframe}
            onChange={(e) => handleChange('wireframe', e.target.checked)}
            aria-label="ワイヤーフレーム"
          />
        </label>
      </div>

      <div className="control-group">
        <label className="label" htmlFor="cube-autorotate-checkbox">
          自動回転
          <input
            id="cube-autorotate-checkbox"
            type="checkbox"
            checked={config.autoRotate}
            onChange={(e) => handleChange('autoRotate', e.target.checked)}
            aria-label="自動回転"
          />
        </label>
      </div>

      <div className="control-group">
        <label className="label" htmlFor="cube-speed-range">
          <span>回転速度</span>
          <span>{config.speed.toFixed(1)}x</span>
        </label>
        <input
          id="cube-speed-range"
          type="range"
          className="range-input"
          min="0.1"
          max="3"
          step="0.1"
          value={config.speed}
          onChange={(e) => handleChange('speed', parseFloat(e.target.value))}
          aria-label="回転速度"
        />
      </div>

      <button className="btn" onClick={onReset} aria-label="設定をリセット">
        設定をリセット
      </button>
    </div>
  );
}

import { Component, ErrorInfo, ReactNode, useState } from 'react'
import { CubeConfig } from './types'
import { defaultConfig } from './constants'
import CubeCanvas from './CubeCanvas'
import ControlPanel from './ControlPanel'
import './index.css'

interface ErrorBoundaryProps {
  children: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
}

class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  state: ErrorBoundaryState = { hasError: false };

  static getDerivedStateFromError(_: Error): ErrorBoundaryState {
    return { hasError: true };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("ErrorBoundary caught an error", error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div style={{ padding: '40px', textAlign: 'center', color: 'var(--text-color)' }}>
          <h2 style={{ marginBottom: '16px' }}>予期せぬエラーが発生しました。</h2>
          <button 
            className="btn" 
            onClick={() => window.location.reload()}
            style={{ marginTop: '20px', maxWidth: '200px', marginInline: 'auto' }}
          >
            再読み込み
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

function MainApp() {
  const [config, setConfig] = useState<CubeConfig>(defaultConfig);

  const handleReset = () => {
    setConfig(defaultConfig);
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">3D 立方体カスタマイザー</h1>
        <p className="subtitle">マウスでドラッグして回転、パネルから見た目をカスタマイズできます</p>
      </header>

      <main className="main-layout">
        <CubeCanvas config={config} />
        <ControlPanel
          config={config}
          onChange={setConfig}
          onReset={handleReset}
        />
      </main>
    </div>
  );
}

export default function App() {
  return (
    <ErrorBoundary>
      <MainApp />
    </ErrorBoundary>
  );
}

import { CubeConfig } from './types'

export const defaultConfig: CubeConfig = {
  color: '#3b82f6',
  wireframe: false,
  autoRotate: true,
  speed: 1.0,
};
